BEGIN
  PERFORM pg_temp.rec('rb_reader_md5', to_jsonb((SELECT md5(prosrc) FROM pg_proc WHERE oid = 'public._mcp_r_list_deals(text,text,integer,timestamptz,uuid)'::regprocedure)));
